PostgreSQL Databases.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(postgresql_databases, "PostgreSQL Databases") {
    Component(patroni_etcd_clustering_engine, "Patroni/etcd Clustering Engine", "Patroni, etcd", "Provides high-availability active-passive clustering with automated failover for PostgreSQL.")
    Component(pgbouncer_connection_pooler, "PgBouncer Connection Pooler", "PgBouncer", "Manages and pools database connections to prevent starvation under heavy concurrent clinical usage.")
    Component(pgaudit_module, "pgaudit Module", "pgaudit", "Captures tamper-evident audit logs of DDL and DML operations on PHI tables.")
}

Rel(pgbouncer_connection_pooler, patroni_etcd_clustering_engine, "Routes pooled SQL queries", "SQL/TLS")
Rel(patroni_etcd_clustering_engine, pgaudit_module, "Generates audit logs", "Internal")

@enduml

Event Broker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Event Broker container

Container_Boundary(event_broker, "Event Broker") {
    Component(Message_Ingestion_Handler, "Message Ingestion Handler", "Apache Kafka / RabbitMQ", "Ingests asynchronous events from microservices via mTLS.")
    Component(Schema_Registry_Validator, "Schema Registry Validator", "Avro/JSON Schema Registry", "Validates incoming event payloads against defined schemas.")
    Component(Event_Routing_Engine, "Event Routing Engine", "Apache Kafka / RabbitMQ Core", "Routes and distributes asynchronous messages to appropriate consuming microservices.")
}

Rel(Message_Ingestion_Handler, Schema_Registry_Validator, "Validates message payloads")
Rel(Schema_Registry_Validator, Event_Routing_Engine, "Forwards validated events for routing")
@enduml

Immutable Audit Storage Sink.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(immutable_audit_storage_sink, "Immutable Audit Storage Sink") {
    Component(AuditIngestionEngine, "Audit Ingestion Engine", "Golang, S3 API", "Receives compliance and audit records securely via mTLS and ingests them into storage.")
    Component(WORMStorageController, "WORM Storage Controller", "AWS S3 Object Lock, MinIO", "Enforces 10-year Write-Once-Read-Many (WORM) retention policies on audit logs.")
    Component(ComplianceQueryAPI, "Compliance Query API", "REST, TLS", "Provides secure, read-only query capabilities for compliance officers using ephemeral credentials.")
}

Rel(AuditIngestionEngine, WORMStorageController, "Writes immutable compliance records to")
Rel(ComplianceQueryAPI, WORMStorageController, "Queries stored audit logs from")
@enduml
